-- November 10: "How to do it" cards (doc: DWTP Medal How-To Cards, approved by Michael).
-- She taps a habit on her medal screen and the steps open under it.
alter table public.ring_items add column if not exists how_to jsonb;

update public.ring_items set how_to = $j${"title": "The Blinking Method", "why": "Your eye muscles are connected to your vagus nerve, which slows your heart rate. This shifts you from fight-or-flight to rest-and-digest in about 2 minutes.", "steps": ["Lie flat in bed. Don't grab your phone and don't check the time.", "Make 10 slow, deliberate blinks.", "Eyes open, look all the way up and hold for 3 seconds. Then left, 3 seconds. Right, 3 seconds. Down, 3 seconds.", "Blink as fast as you can, a rapid flutter, for 60 seconds.", "Finish with 3 slow blinks while taking deep breaths, then let your eyes stay closed.", "Don't *try* to fall asleep. Just let your eyelids get heavy. Still awake after 10 minutes? Do it again."]}$j$::jsonb
  where ring_id = 'db1fbde6-cd3f-5e03-a35c-840c3026d00f' and (title ilike '%blinking%');
update public.ring_items set how_to = $j${"title": "The No-Nap Nap (NSDR)", "why": "10–20 minutes of Non-Sleep Deep Rest gives you the recovery of a nap without the grogginess, and it won't hurt your sleep tonight.", "steps": ["Around 2:30 PM, sit or recline somewhere quiet (your desk or your car works). Headphones in, phone on Do Not Disturb.", "Close your eyes. Take 3 deep breaths in through your nose and out with a long sigh through your mouth.", "Let your breathing go back to normal. Silently repeat a short intention, like “I am calm and rested.”", "Scan your body slowly: face, jaw, tongue, then down your right arm, side and leg, then your left. Or just follow a 10–20 minute guided NSDR audio.", "You're not trying to sleep. You're resting in the space between awake and asleep.", "**Reactivate (3 minutes):** a glass of cold water, step outside into daylight, and 5 deep breaths (in for 4, out for 8)."]}$j$::jsonb
  where ring_id = '200cbae3-89df-59db-81df-3508e6f8eccf' and (title ilike '%NSDR%');
update public.ring_items set how_to = $j${"title": "The 10-3-2-1-0 Rule", "why": "Each step removes one thing that keeps your brain awake at night.", "steps": ["**10 hours** before bed: no more caffeine.", "**3 hours** before bed: no more food or alcohol.", "**2 hours** before bed: no more work. Close the laptop and the work email.", "**1 hour** before bed: no more screens. Read, stretch, talk.", "**0** times you hit snooze in the morning.", "Work it out once from your bedtime. In bed at 10 PM? Last coffee by noon, dinner done by 7, work done by 8, screens off by 9."]}$j$::jsonb
  where ring_id = '38b9f5cb-dfab-57b7-9001-19305d94f47a' and (title ilike '%10-3-2-1-0%');
update public.ring_items set how_to = $j${"title": "Your Baseline (maintenance calories)", "why": "Before we cut anything, you prove you can hit a number. That's the skill everything else is built on.", "steps": ["Log every meal and weigh in every morning for 14 days. Eat normally.", "Michael looks at your logs and your weight trend and sets your maintenance calories: what you can eat without gaining or losing.", "Your number shows on your Today screen.", "Each day, land within 100 calories of it, over or under.", "Plan your biggest meal around what's left. Check the Today screen before dinner."]}$j$::jsonb
  where ring_id = 'a64da852-0a8d-5c1d-b78f-756fe922061a' and (title ilike '%maintenance%');
update public.ring_items set how_to = $j${"title": "Log Like a Pro", "why": "The calories you don't log are usually why the scale won't move.", "steps": ["Log ingredient by ingredient. Not “chicken salad,” but the chicken, the greens, the dressing, the cheese.", "Log the cooking oil and butter. A tablespoon of oil is about 120 calories.", "Log sauces, dressings and creamer in your coffee.", "Log the tiny bites: the handful of almonds, the fries off your kid's plate, tasting while you cook.", "Weigh foods with a food scale when you can, at least for the first couple of weeks. Eyeballing is almost always low."]}$j$::jsonb
  where ring_id = 'c3d972f1-ba35-52d1-b44b-b434b2c10c23' and (title ilike '%ingredient by ingredient%' or title ilike '%tiny calories%');
update public.ring_items set how_to = $j${"title": "Smart Deficit and Diet Breaks", "why": "A small deficit loses 1–2 lbs a week without starving you, and diet breaks keep your body from fighting back.", "steps": ["Take your maintenance calories and eat 15–20% less. Maintenance of 1,800? Your target is about 1,450–1,550.", "Never go under 1,200 calories. Ever.", "Keep protein at 40 g+ per meal. Protein is what protects your muscle while you lose fat.", "Every 8–12 weeks in a deficit, take a diet break: one full week back at maintenance.", "A diet break is part of the plan, not falling off. Expect the scale to bump up a pound or two from water. It comes back off."]}$j$::jsonb
  where ring_id = 'ebe6a6b1-dac9-529e-910b-5c884e6c80c0' and (title ilike '%below maintenance%' or title ilike '%diet break%');
update public.ring_items set how_to = $j${"title": "Swaps", "why": "Same foods you love, more nutrients, usually fewer calories.", "steps": ["Michael picks 3 swaps for you from what's actually in your food logs.", "Examples: 93% lean ground beef instead of 80%. Plain Greek yogurt with a little honey instead of flavored yogurt. Protein powder added to your coffee or oatmeal.", "Make each swap every time that food comes up, every day.", "Once a swap feels normal, ask Michael for the next one."]}$j$::jsonb
  where ring_id = 'dba8feac-e929-5342-a9a0-7685906d0a91' and (title ilike '%swap%');
update public.ring_items set how_to = $j${"title": "Ingredient Prep", "why": "Meal prep gets boring by Wednesday. Prepping ingredients means every meal takes minutes and you still choose what you're in the mood for.", "steps": ["Once a week, pick 30–60 minutes.", "Chop your vegetables and store them in glass Tupperware.", "Mix your seasonings for the week's meats in small containers.", "Bag the dry ingredients for bowls and shakes (oats, chia, protein powder).", "Cook a batch of potatoes or rice to reheat.", "During the week, just combine and cook."]}$j$::jsonb
  where ring_id = 'fd2ff797-a58a-529a-9fd5-ffd0d67b228f' and (title ilike '%prep%');
update public.ring_items set how_to = $j${"title": "Your Reason Why and the 2-Minute Visualization", "why": "Motivation fades in minutes. Your reason why lasts, as long as you see it every day.", "steps": ["Write down why you're doing this. Then ask yourself “why does that matter?” three times. “Lose 20 pounds” becomes “be the mom who keeps up with her kids on vacation.”", "Keep it where you'll see it: the notes on your phone, or a sticky note on your mirror.", "Every day, take 2 minutes. Close your eyes and picture a normal day once you're there: how you wake up, what you wear, how you feel walking into a room.", "Make it vivid. Where are you, who's with you, what are you doing?", "When you're about to skip a workout or blow your calories, read your reason why first."]}$j$::jsonb
  where ring_id = '357d7314-a692-55ba-bae0-90075f0b17ae' and (title ilike '%reason why%' or title ilike '%visualization%');
update public.ring_items set how_to = $j${"title": "The Eisenhower Matrix", "why": "Most of what fills your day is urgent, not important. This shows you the difference in about 5 minutes.", "steps": ["Before bed, list everything on your plate for tomorrow.", "Sort each item into one of four boxes:\n• **Urgent and important:** do it first.\n• **Important, not urgent:** schedule it. Your workouts, meal prep and sleep live here.\n• **Urgent, not important:** delegate it, or keep it short.\n• **Neither:** drop it.", "Put tomorrow's “do first” and “schedule” items on your calendar with times.", "Protect the “important, not urgent” box. That's where the results come from."]}$j$::jsonb
  where ring_id = '5d22d33d-d58c-5755-90c3-1732a81cb66b' and (title ilike '%eisenhower%');
update public.ring_items set how_to = $j${"title": "The Four Non-Negotiables", "why": "When everything else falls apart, these four keep your day moving forward.", "steps": ["Pick one non-negotiable in each area: **body**, **food**, **love** and **career or finances**.", "Make each one small and specific. For example: body, 10,000 steps. Food, hit your calories. Love, one appreciation text. Career, one hour on your most important project.", "Write tomorrow's four into your plan before bed.", "Hit all four every day, no matter what else happens."]}$j$::jsonb
  where ring_id = '5d22d33d-d58c-5755-90c3-1732a81cb66b' and (title ilike '%non-negotiable%');
update public.ring_items set how_to = $j${"title": "The 3-to-1 Rule", "why": "Your brain holds onto the bad stuff and forgets the good. It's always three to one: balancing every bad thing with three good ones keeps one setback from turning into a bad week.", "steps": ["When something goes wrong (a bad weigh-in, an argument, a missed workout), stop.", "Write down 3 good things that happened today, big or small.", "Then write the one thing you'll do next. Not what went wrong, just the next step.", "Remember the valley of despair: every real change has a hard middle where it feels like nothing's working. That's normal, and it's right before things click. Keep going."]}$j$::jsonb
  where ring_id = 'cf5c3e07-38ea-5aa8-b658-5c2a8fb3d2f7' and (title ilike '%3 good%' or title ilike '%three good%' or title ilike '%valley%');
update public.ring_items set how_to = $j${"title": "Hill Sprints", "why": "Short, all-out efforts are great for your hormones and your mood, and the whole thing takes about 15 minutes.", "steps": ["Warm up with 5 minutes of brisk walking, then a few leg swings and walking lunges.", "Find a hill you can sprint up for 10–15 seconds.", "Sprint 1 at about 50% effort. Sprint 2 at 75%. Sprints 3 to 6 all-out.", "Walk back down slowly between sprints. That's your rest. Take more if you need it.", "No hill? Do the same on a bike: 15–20 seconds hard, about a minute easy, 6 times.", "Once a week, on its own day if you can."]}$j$::jsonb
  where ring_id = 'b3e6e67a-3a75-58ad-85dd-045938ea4f79' and (title ilike '%sprint%');
update public.ring_items set how_to = $j${"title": "Sled Pushes", "why": "It's hard work that's easy on your joints. There's no landing, no pounding, just pushing.", "steps": ["Load the sled light enough that you can keep moving the whole length. Speed matters more than weight.", "Hands on the poles, arms straight or slightly bent, body leaning forward at about 45 degrees.", "Drive with short, powerful steps, pushing through the balls of your feet.", "Push it to the end, rest until your breathing settles, then push it back. That's 2.", "Do 10 pushes total, all on one day.", "No sled? Push a loaded car in neutral on flat ground with someone steering, or ask Michael for an option."]}$j$::jsonb
  where ring_id = 'b81b378e-0e1a-5c29-bdb9-fdeadbc5c9fe' and (title ilike '%sled%');
update public.ring_items set how_to = $j${"title": "The Deep Squat Hold", "why": "Sitting all day locks up your hips and ankles. Holding a deep squat opens them back up.", "steps": ["Stand with your feet about shoulder-width apart, toes turned out a little.", "Sink down as low as you can, keeping your heels on the floor.", "Hold onto a doorframe, a counter or a post if you need to.", "Keep your chest up and push your knees out gently with your elbows.", "Start with 20–30 seconds and add a few seconds each day, working up to 2 minutes.", "Heels pop up? Put a folded towel under them for now."]}$j$::jsonb
  where ring_id = '0d24b7e8-3eef-5e1b-92cc-d82c1dcdbd1f' and (title ilike '%squat hold%');

-- Check: should list every card's habit at least once.
select r.name as medal, i.title, i.how_to->>'title' as card from public.ring_items i join public.rings r on r.id = i.ring_id where i.how_to is not null order by r.name;
